from math import factorial

def check_expression(expr):
    tokens = [token.strip() for token in expr.split('/')]  # Split expression into tokens
    stack = []
    balanced = True

    # Check left-hand side expression
    for token in tokens[:-1]:
        if not stack or token == '(':
            stack.append(token)
        else:
            if balanced:
                return False, "Expression is balanced but has unmatched pair"
            if not stack or token == ')':
                if not stack:
                    return False, "Expression is not balanced"
            balanced = False

    # Check right-hand side expression
    for token in tokens[-1]:
        if not stack or token == ')':
            if not stack:
                return False, "Expression is not balanced"
            if not balanced:
                return False, "Expression is not balanced"

    return balanced, "Expression is balanced"

# Test the function
