assert check_expression("[]{}") == (True, "Expression is balanced")
assert check_expression("unbalanced") == (-1, "Expression is not balanced")

def check_expression(expression):
    balanced, msg = check_expression(expression)
    if msg == "Expression is balanced":
        return True, "Expression is balanced"
    else:
        return False, msg

# Example usage
