from itertools import combinations

def largest_subset(arr, elems):
    """Find the largest subset where each pair is divisible by the surest
    divisor in the subset defined by 'elems'."""
    def is_divisible(subset, divisor):
        return all(subset[i] % divisor == 0 for i in range(len(subset))) 

    # Generate all possible subsets of `elems` and find the longest one
    def find_longest_subset(surest):
        subsets = [set() for _ in range(len(surest))]
        for r in range(1, len(surest) + 1):
            for combo in combinations(surest, r):
                if not is_divisible(list(combo), surest[0]):
                    continue
                subsets[r].append(combo)
        return max(subsets, key=len)

    # Start with the given slice and extend to its end if possible within `elems`
    surest = [ele for sublist in arr for ele in sublist if ele == surest[0]]
    if not surest:
        return None

    return find_longest_subset(surest)

