    return True

def prime_factors(n):
    """Return the distinct prime factors of a number."""
    factors = set()
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.add(i)
    if n > 1:
        factors.add(n)
    return factors

def count_Fac(n):
    """Count the number of distinct power of prime factor of given number."""
    def get_exponent(f, v):
        """Calculate the exponent of a prime p in the factorization of v."""
        exponent = 0
        while v % p == 0:
            exponent += 1
            v //= p
        return exponent

    primes = [i for i in range(2, n + 1) if is_prime(i)]
    factors = prime_factors(n)
    exponents = {k: 0 for k in factors}
    for p in primes:
        e = get_exponent(p, n)
        for f in factors:
            exponents[f] = min(exponents[f], e)

    # Return the maximum exponent plus 1
    return len(exponents)

