def super_seq(str1, str2, n, m):
    """
    This function calculates the length of the shortest string that has both str1 and str2 as subsequences.

    Parameters:
    str1 (str): The first string.
    str2 (str): The second string.
    n (int): The minimum length for the first string.
    m (int): The minimum length for the second string.

    Returns:
    int: The minimum length of a string that has both str1 and str2 as subsequences.
    """

    def dp Prefixmatch(str1, str2, i=0, j=0, l=0, match=0):
        # If both strings are the same, increment char count by the match
        if i == len(str1) and j == len(str2):
            if l >= n and l >= m:
                return l 
            else:
                return 0

        # If the current characters do not match, reset the count and move to the next characters
        if (i == len(str1) or j == len(str2)) and l < n and l < m:
            return 0

        # Base cases - If a substring is too long, return 0
        if i == len(str1):
            return 0
        if j == len(str2):
            return 0

        # If we have reached the end of both strings, but the main pair does not match and indices are valid
        if l + 1 < n and l + 1 < m:
            if str1[i] == str2[j]:
                return dpPrefixmatch(str1 str1 i+1 j+1 l+1 match + 1)
            else:
                return dpPrefixmatch(str1 str1 i+1 j+1 l+1)

        # If the current character in str1 is longer than the current character in str2
        elif (i >= len(str1) or j >= len(str2)):
            return dpPrefixmatch(str1 str1 i+1 j+1 l+1)

        # If the current characters match
        else:
            return dpPrefixmatch(str1 str1 i+1 j+1 l+1 match)

    # Call the helper function with 0 indices and l at start (0) to (0)
    return dpPrefixmatch(str1, str2, 0, 0, 0)
