from typing import List

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pairs: List[Pair], target: int) -> int:
    # Sort the pairs by end of the section
    pairs.sort(key=lambda x: x.end)

    # Function to find the longest chain starting at a given length
    def find_longest_chain(length: int) -> int:
        dp = [0] * (length + 1)
        dp[0] = 1  # Base case: no pairs needed to fill length 0

        for pair in pairs:
            for i in range(length, pair.end - 1, -1):
                dp[i] = max(dp[i], dp[i - pair.start] + 1)

        return dp[length]

    # Generate a range of lengths from min to max possible
    max_length = max(pair.end - pair.start for pair in pairs)
    for length in range(max_length, -1, -1):
        if length > 0 and find_longest_chain(length) == target:
            return length

    return 0  # In case the target cannot be achieved

