from typing import List, TypeVar, Generic, Optional
from sortedcontainers import SortedList
from math import inf

T = TypeVar('T')

class Pair(Generic[T]):
    def __init__(self, a: T, b: T):
        self.a = a
        self.b = b

    def __lt__(self, other: T) -> bool:
        if self.b == other.b:
            return self.a < other.a
        return self.b < other.b

class MaxChainLengthFinder(Generic[T]):
    def __init__(self, pairs):
        self.pairs = pairs

    def max_chain_length(self, n: int) -> int:
        pairs_list = SortedList([[0, 0] for _ in range(n + 1)])
        for p in self.pairs:
            pairs_list.add([p.a, p.b])
            pairs_list.add([p.b, p.a])
        maximum_chains = 0
        seen = [False] * (n + 1)
        chains = 0
        while chains < n:
            next_node = pairs_list.pop()
            if seen[next_node[0]] or seen[next_node[1]]:
                continue
            seen[next_node[0]] = seen[next_node[1]] = True
            chains += 1
            maximum_chains = max(maximum_chains, chains)
            for p in self.pairs:
                if next_node[0] == p.a or next_node[0] == p.b or next_node[1] == p.a or next_node[1] == p.b:
                    pairs_list.add([p.a, p.b])
                    pairs_list.add([p.b, p.a])
        return maximum_chains

