def count_Fac(n):
    """
    Count the number of distinct prime factors of the given number
    """
    prime_factors = set()
    # Check for each number <= sqrt(n) whether 2 is a factor
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            if i in prime_factors:
                break
            prime_factors.add(i)
            n /= i

    # Check for each odd factor less than sqrt(n)
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            if i in prime_factors:
                break
            prime_factors.add(i)
            n /= i

    # If n is a prime greater than 2, then it is its only factor
    if n > 2 and n in prime_factors:
        prime_factors.remove(n)  # No need to count it again

