import math

def count_Fac(n):
    """
    Given a positive integer n, returns the count of distinct non-zero digit prime factors.
    Prime factors are self-explanatory, and non-zero means the factors cannot be 0.

    Examples:
    >>> count_Fac(24)
    3
    >>> count_Fac(192)
    4
    """

    def is_prime_factors_prime(n):
        # Check if all prime factors are prime themselves using a helper function
        def is_prime(num):
            if num < 2:
                return False
            for i in range(2, int(math.sqrt(num)) + 1):
                if num % i == 0:
                    return False
            return True

        def factors(n):
            factors = []
            for i in range(2, int(math.sqrt(n)) + 1):
                if n % i == 0:
                    factors.append(i)
                    if i != n // i:
                        factors.append(n // i)
            return sorted(factors)

        prime_factors = factors(n)
        return all(is_prime(factor) for factor in prime_factors)

    return len([factor for factor in range(2, n) if n % factor == 0 and is_prime_factors_prime(factor)])

