def remove_similar_row(matrix):
    if not matrix:
        return {}

    # Track the occurrence of dictionaries in the matrix
    unique_rows = set()
    duplicate_rows = defaultdict(set)

    for row in matrix:
        for r in row:
            duplicate_rows[r].add(row)

    result = []
    for r in matrix:
        if len(duplicate_rows[r]) == 1:  # Row is unique
            result.append(r)

