from typing import List

def min_sum_path(triangle: List[List[int]]) -> int:
    """
    Finds the minimum path sum in a triangle.

    Args:
    triangle: A list of lists of integers representing a triangle.

    Returns:
    An integer representing the minimum path sum.
    """

    for row in range(1, len(triangle)):
        for col in range(len(triangle[row])):
            if col == 0:
                triangle[row][col] += triangle[row - 1][col]
            elif col == len(triangle[row]) - 1:
                triangle[row][col] += triangle[row - 1][col - 1]
            else:
                triangle[row][col] += min(triangle[row - 1][col - 1], triangle[row - 1][col])

    return min(triangle[-1])

