import sys

class MatrixWalker:
    def maxAveragePath(self, matrix: List[List[int]], n: int) -> float:
        if not matrix or not matrix[0]:
            raise ValueError("Matrix cannot be empty")

        numRows, numCols = len(matrix), len(matrix[0])
        maxAverage = float('-inf')
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        def isValid(x, y):
            return 0 <= x < numRows and 0 <= y < numCols

        def calculateAverage(x, y):
            total = 0
            count = 0
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if isValid(nx, ny) and matrix[nx][ny] < matrix[x][y]:
                    total += matrix[nx][ny]
                    count += 1
            return (total + matrix[x][y]) / (1 if count == 0 else count + 1)

        for i in range(numRows):
            for j in range(numCols):
                maxAverage = max(maxAverage, calculateAverage(i, j))

        return maxAverage

