def maxAverageOfPath(matrix, k):
    n = len(matrix)
    if n % k != 0:
        return float('inf')  # Not sufficient rows to form k paths

    avg_set = set()
    max_avg = float('-inf')

    for i in range(n):
        flat_row = sum(matrix[j][i] for j in range(n))
        avg_set.add(flat_row)

    max_avg = max(avg_set)

    # Adjust if the matrix row count is insufficient to full fill subset of k
    if n - k < max_avg:
        if (n - k) <= k:
            return float('inf')
        else:
            return max_avg - (n - k + 1)

    return max_avg

