def count_Pairs(arr, k):
    n = len(arr)
    arr.sort()  # Sort the array to simplify the counting process
    count = 0  # Initialize the count of pairs
    start = 0  # Start index for the sliding window

    for end in range(n):
        # If the difference between the current element and any element in the current window is less than or equal to k
        while (end - start + 1) > (k * 2 + 1):
            if arr[end] - arr[start] > k:
                count -= n - end  # Adjust the count by the number of invalid pairs
                start += 1  # Move the start pointer to the right
            else:
                start += 1  # Move the start pointer to the right

    count += n - (end - start + 1)  # Add pairs in the current window

    # Adjust for the sliding window shrinks when the end pointer crosses maximum number in the window
    while (end - start + 1) > (k * 2 + 1):
        if arr[end] - arr[start] > k:
            count -= 1
        start += 1

    return count
