def count_Pairs(array, index_count):
    if index_count < 2:
        return 0
    pairs = 0
    n = len(array)
    for i in range(n - 1):
        if array[i] == array[i + 1]:
            pairs += 1
            # Ensure we do not count pairs more than twice by setting previous_index to the current index
            previous_index = i - 1
            if previous_index >= 0 and array[previous_index] == array[i + 1]:
                pairs -= 1
                # Move the previous_index one step back to avoid double counting
                previous_index = i - 2
                array[previous_index + 1] = 0
    return pairs * (index_count - 1)
