def super_seq(str1, str2, index1, index2):
    # If either index is -1, str1 or str2 has been exhausted
    if index1 == -1 or index2 == -1:
        return max(len(str1), len(str2))

    # If there is a longest common subsequence of length < index values, choose it
    elif index1 < index2:
        return super_seq(str1, str2, index1, index2 - 1)

    # Otherwise, check both str1[char:index1] and str2[char:index2] seperately and collect the result
    else:
        return min(
            1 + super_seq(str1, str2, index1 - 1, index2),
            1 + super_seq(str1, str2, index1, index2 - 1)
        )

