def super_seq(a, b, m, n):
    # Creating a 2D DP table with m+1 rows and n+1 columns initialized to infinity
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]

    # Base case initialization for empty strings
    dp[0][0] = 0

    # Filling the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]
