def super_seq(str1, str2, m, n):
    # Initialize a DP table where super_seq[i][j] is the length of the shortest
    # string containing both 'str1[0..i-1]' and 'str2[0..j-1]'
    super_seq = [[0 for j in range(n+1)] for i in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                super_seq[i][j] = 1 + super_seq[i-1][j-1]
            else:
                super_seq[i][j] = max(super_seq[i-1][j], super_seq[i][j-1])
    # The length of the shortest string is super_seq[m][n]
    return super_seq[m][n]

