def count_duplic(nums):
    # Initialize variables to keep track of frequency and last occurrence position
    freq = {}
    last_occurrence = {}

    duplicates = []
    duplicate_freq = []

    # Iterate through the list
    for i, num in enumerate(nums):
        # If the number is at a new position, record its frequency
        if num not in last_occurrence:
            last_occurrence[num] = i
            freq[num] = 1
        else:
            # If the number has appeared before, record its frequency if different from the last position
            if freq[num] != i - last_occurrence[num]:
                duplicates.append(num)
                duplicate_freq.append(freq[num])
            freq[num] = i

    return (duplicates, duplicate_freq)
