def count_duplic(nums):
    # Dictionary to hold the count of consecutive duplicates
    count_dict = {}

    # Creating lists of consecutive duplicates and their counts
    consecutive_dups = []
    count = 0
    max_count = 0

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            count += 1
            if count > max_count:
                max_count = count
                consecutive_dups.append([nums[i - 1], count])
            elif count == max_count:
                consecutive_dups[-1][1] += 1
        else:
            count = 0

    # Convert the last block of consecutive duplicates to the max count
    if consecutive_dups:
        consecutive_dups[-1][1] += 1

    return (consecutive_dups, [float('inf') if not consecutive_dups else max(consecutive_dups, key=lambda x: x[1])[1]])

