def count_unique_sublists(lst):
    # Dictionary to store the frequency of unique elements
    frequency_dict = {}
    # Set to store unique elements
    unique_elements = set()

    # Count the frequency and collect unique elements
    for sublist in lst:
        for element in sublist:
            unique_elements.add(element)
            if element not in frequency_dict:
                frequency_dict[element] = 1
            else:
                frequency_dict[element] += 1

    # Rebuild the dict with tuples as keys and counts as values
    unique_sublists = {}
    for element, count in frequency_dict.items():
        unique_sublists[(element,)] = count

