from typing import List, Tuple

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pairs: List[Pair], k: int) -> int:
    """
    Finds the length of the longest chain that can be formed from the given pairs.

    :param pairs: List of Pair objects representing the start and end points of chains.
    :param k: The number of chains to consider.
    :return: The length of the longest chain that can be formed.
    """
    pairs.sort(key=lambda x: x.end)  # Sort pairs by end point
    dp = [1] * k  # Initialize DP array with 1s
    for i in range(1, k):
        for j in range(i):
            if pairs[i].start >= pairs[j].end:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

# Example usage
if __name__ == "__main__":
    pairs = [Pair(5, 24), Pair(15, 25), Pair(27, 40), Pair(50, 60)]
    k = 4
    print(max_chain_length(pairs, k))  # Expected output: 3
```

